package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	flipt "github.com/markphelps/flipt/rpc/flipt"
	"gopkg.in/yaml.v2"
)

type creator interface {
	CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
	CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
	CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
	CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
	CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
	CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
}

type Importer struct {
	store creator
}

func NewImporter(store creator) *Importer { return &Importer{store: store} }

// convert makes YAML maps safe for encoding/json, including maps within arrays.
func convert(value interface{}) interface{} {
	switch v := value.(type) {
	case map[interface{}]interface{}:
		result := make(map[string]interface{}, len(v))
		for key, item := range v {
			result[fmt.Sprint(key)] = convert(item)
		}
		return result
	case map[string]interface{}:
		result := make(map[string]interface{}, len(v))
		for key, item := range v {
			result[key] = convert(item)
		}
		return result
	case []interface{}:
		for i, item := range v {
			v[i] = convert(item)
		}
		return v
	default:
		return value
	}
}

func (i *Importer) Import(ctx context.Context, r io.Reader) error {
	var doc Document
	if err := yaml.NewDecoder(r).Decode(&doc); err != nil {
		return fmt.Errorf("importing: %w", err)
	}
	// Variants must exist before rules reference their IDs. Segments must exist
	// before rules reference their keys.
	createdVariants := make(map[string]*flipt.Variant)
	for _, f := range doc.Flags {
		if _, err := i.store.CreateFlag(ctx, &flipt.CreateFlagRequest{
			Key: f.Key, Name: f.Name, Description: f.Description, Enabled: f.Enabled,
		}); err != nil {
			return fmt.Errorf("importing flag %q: %w", f.Key, err)
		}
		for _, v := range f.Variants {
			var attachment string
			if v.Attachment != nil || v.attachmentPresent {
				// Existing exports may contain JSON text as a YAML scalar.
				if raw, ok := v.Attachment.(string); ok && json.Valid([]byte(raw)) {
					attachment = raw
				} else {
					encoded, err := json.Marshal(convert(v.Attachment))
					if err != nil {
						return fmt.Errorf("encoding attachment for variant %q of flag %q: %w", v.Key, f.Key, err)
					}
					attachment = string(encoded)
				}
			}
			variant, err := i.store.CreateVariant(ctx, &flipt.CreateVariantRequest{
				FlagKey: f.Key, Key: v.Key, Name: v.Name, Description: v.Description, Attachment: attachment,
			})
			if err != nil {
				return fmt.Errorf("importing variant %q of flag %q: %w", v.Key, f.Key, err)
			}
			createdVariants[f.Key+":"+v.Key] = variant
		}
	}
	for _, s := range doc.Segments {
		matchType := flipt.MatchType_ALL_MATCH_TYPE
		if s.MatchType != "" {
			value, ok := flipt.MatchType_value[s.MatchType]
			if !ok {
				return fmt.Errorf("invalid match type %q for segment %q", s.MatchType, s.Key)
			}
			matchType = flipt.MatchType(value)
		}
		if _, err := i.store.CreateSegment(ctx, &flipt.CreateSegmentRequest{
			Key: s.Key, Name: s.Name, Description: s.Description, MatchType: matchType,
		}); err != nil {
			return fmt.Errorf("importing segment %q: %w", s.Key, err)
		}
		for _, c := range s.Constraints {
			if _, err := i.store.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
				SegmentKey: s.Key, Type: flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
				Property: c.Property, Operator: c.Operator, Value: c.Value,
			}); err != nil {
				return fmt.Errorf("importing constraint for segment %q: %w", s.Key, err)
			}
		}
	}
	for _, f := range doc.Flags {
		for _, r := range f.Rules {
			rule, err := i.store.CreateRule(ctx, &flipt.CreateRuleRequest{
				FlagKey: f.Key, SegmentKey: r.SegmentKey, Rank: int32(r.Rank),
			})
			if err != nil {
				return fmt.Errorf("importing rule for flag %q: %w", f.Key, err)
			}
			for _, d := range r.Distributions {
				variant, ok := createdVariants[f.Key+":"+d.VariantKey]
				if !ok {
					return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
				}
				if _, err := i.store.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
					FlagKey: f.Key, RuleId: rule.Id, VariantId: variant.Id, Rollout: d.Rollout,
				}); err != nil {
					return fmt.Errorf("importing distribution for flag %q: %w", f.Key, err)
				}
			}
		}
	}
	return nil
}
package ext

import (
	"context"
	"encoding/json"
	"fmt"
	"io"

	flipt "github.com/markphelps/flipt/rpc/flipt"
	"github.com/markphelps/flipt/storage"
	"gopkg.in/yaml.v2"
)

type lister interface {
	ListFlags(context.Context, ...storage.QueryOption) ([]*flipt.Flag, error)
	ListRules(context.Context, string, ...storage.QueryOption) ([]*flipt.Rule, error)
	ListSegments(context.Context, ...storage.QueryOption) ([]*flipt.Segment, error)
}

type Exporter struct {
	store     lister
	batchSize uint64
}

func NewExporter(store lister) *Exporter {
	return &Exporter{store: store, batchSize: 25}
}

func (e *Exporter) Export(ctx context.Context, w io.Writer) error {
	doc := new(Document)
	for offset := uint64(0); ; offset += e.batchSize {
		flags, err := e.store.ListFlags(ctx, storage.WithOffset(offset), storage.WithLimit(e.batchSize))
		if err != nil {
			return fmt.Errorf("getting flags: %w", err)
		}
		for _, f := range flags {
			flag := &Flag{Key: f.Key, Name: f.Name, Description: f.Description, Enabled: f.Enabled}
			variantKeys := make(map[string]string, len(f.Variants))
			for _, v := range f.Variants {
				variant := &Variant{Key: v.Key, Name: v.Name, Description: v.Description}
				if v.Attachment != "" {
					variant.attachmentPresent = true
					if err := json.Unmarshal([]byte(v.Attachment), &variant.Attachment); err != nil {
						return fmt.Errorf("decoding attachment for variant %q of flag %q: %w", v.Key, f.Key, err)
					}
				}
				flag.Variants = append(flag.Variants, variant)
				variantKeys[v.Id] = v.Key
			}
			rules, err := e.store.ListRules(ctx, f.Key)
			if err != nil {
				return fmt.Errorf("getting rules for flag %q: %w", f.Key, err)
			}
			for _, r := range rules {
				rule := &Rule{SegmentKey: r.SegmentKey, Rank: uint(r.Rank)}
				for _, d := range r.Distributions {
					rule.Distributions = append(rule.Distributions, &Distribution{
						VariantKey: variantKeys[d.VariantId], Rollout: d.Rollout,
					})
				}
				flag.Rules = append(flag.Rules, rule)
			}
			doc.Flags = append(doc.Flags, flag)
		}
		if uint64(len(flags)) < e.batchSize {
			break
		}
	}
	for offset := uint64(0); ; offset += e.batchSize {
		segments, err := e.store.ListSegments(ctx, storage.WithOffset(offset), storage.WithLimit(e.batchSize))
		if err != nil {
			return fmt.Errorf("getting segments: %w", err)
		}
		for _, s := range segments {
			segment := &Segment{Key: s.Key, Name: s.Name, Description: s.Description}
			if s.MatchType != flipt.MatchType_ALL_MATCH_TYPE {
				segment.MatchType = s.MatchType.String()
			}
			for _, c := range s.Constraints {
				segment.Constraints = append(segment.Constraints, &Constraint{
					Type: c.Type.String(), Property: c.Property, Operator: c.Operator, Value: c.Value,
				})
			}
			doc.Segments = append(doc.Segments, segment)
		}
		if uint64(len(segments)) < e.batchSize {
			break
		}
	}
	enc := yaml.NewEncoder(w)
	if err := enc.Encode(doc); err != nil {
		return fmt.Errorf("exporting: %w", err)
	}
	return enc.Close()
}
package ext

// Document is the portable YAML representation of flags and segments.
type Document struct {
	Flags    []*Flag    `yaml:"flags,omitempty"`
	Segments []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
	Key         string     `yaml:"key,omitempty"`
	Name        string     `yaml:"name,omitempty"`
	Description string     `yaml:"description,omitempty"`
	Enabled     bool       `yaml:"enabled"`
	Variants    []*Variant `yaml:"variants,omitempty"`
	Rules       []*Rule    `yaml:"rules,omitempty"`
}

type Variant struct {
	Key               string      `yaml:"key,omitempty"`
	Name              string      `yaml:"name,omitempty"`
	Description       string      `yaml:"description,omitempty"`
	Attachment        interface{} `yaml:"attachment,omitempty"`
	attachmentPresent bool
}

// MarshalYAML keeps an explicit JSON null distinct from an absent attachment.
func (v *Variant) MarshalYAML() (interface{}, error) {
	type plain Variant
	if !v.attachmentPresent {
		return (*plain)(v), nil
	}
	return struct {
		Key         string      `yaml:"key,omitempty"`
		Name        string      `yaml:"name,omitempty"`
		Description string      `yaml:"description,omitempty"`
		Attachment  interface{} `yaml:"attachment"`
	}{v.Key, v.Name, v.Description, v.Attachment}, nil
}

// UnmarshalYAML records whether the attachment key was supplied, including null.
func (v *Variant) UnmarshalYAML(unmarshal func(interface{}) error) error {
	type plain Variant
	if err := unmarshal((*plain)(v)); err != nil {
		return err
	}
	var fields map[interface{}]interface{}
	if err := unmarshal(&fields); err != nil {
		return err
	}
	_, v.attachmentPresent = fields["attachment"]
	return nil
}

type Rule struct {
	SegmentKey    string          `yaml:"segment,omitempty"`
	Rank          uint            `yaml:"rank,omitempty"`
	Distributions []*Distribution `yaml:"distributions,omitempty"`
}

type Distribution struct {
	VariantKey string  `yaml:"variant,omitempty"`
	Rollout    float32 `yaml:"rollout,omitempty"`
}

type Segment struct {
	Key         string        `yaml:"key,omitempty"`
	Name        string        `yaml:"name,omitempty"`
	Description string        `yaml:"description,omitempty"`
	MatchType   string        `yaml:"match_type,omitempty"`
	Constraints []*Constraint `yaml:"constraints,omitempty"`
}

type Constraint struct {
	Type     string `yaml:"type,omitempty"`
	Property string `yaml:"property,omitempty"`
	Operator string `yaml:"operator,omitempty"`
	Value    string `yaml:"value,omitempty"`
}

package ext

import (
	"bytes"
	"context"
	"encoding/json"
	"reflect"
	"strings"
	"testing"

	flipt "github.com/markphelps/flipt/rpc/flipt"
	"github.com/markphelps/flipt/storage"
	"gopkg.in/yaml.v2"
)

type memoryStore struct {
	flags         []*flipt.Flag
	segments      []*flipt.Segment
	rules         []*flipt.Rule
	variants      []*flipt.CreateVariantRequest
	distributions []*flipt.CreateDistributionRequest
}

func (m *memoryStore) ListFlags(_ context.Context, opts ...storage.QueryOption) ([]*flipt.Flag, error) {
	start, end := pageBounds(len(m.flags), opts...)
	return m.flags[start:end], nil
}
func (m *memoryStore) ListSegments(_ context.Context, opts ...storage.QueryOption) ([]*flipt.Segment, error) {
	start, end := pageBounds(len(m.segments), opts...)
	return m.segments[start:end], nil
}
func (m *memoryStore) ListRules(_ context.Context, _ string, _ ...storage.QueryOption) ([]*flipt.Rule, error) {
	return m.rules, nil
}
func pageBounds(length int, opts ...storage.QueryOption) (int, int) {
	var p storage.QueryParams
	for _, opt := range opts {
		opt(&p)
	}
	if p.Offset >= uint64(length) {
		return length, length
	}
	end := p.Offset + p.Limit
	if end > uint64(length) {
		end = uint64(length)
	}
	return int(p.Offset), int(end)
}
func (m *memoryStore) CreateFlag(_ context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
	f := &flipt.Flag{Key: r.Key, Name: r.Name, Description: r.Description, Enabled: r.Enabled}
	m.flags = append(m.flags, f)
	return f, nil
}
func (m *memoryStore) CreateVariant(_ context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) {
	m.variants = append(m.variants, r)
	v := &flipt.Variant{Id: r.Key + "-id", Key: r.Key, Name: r.Name, Description: r.Description, Attachment: r.Attachment}
	for _, f := range m.flags {
		if f.Key == r.FlagKey {
			f.Variants = append(f.Variants, v)
		}
	}
	return v, nil
}
func (m *memoryStore) CreateSegment(_ context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment, error) {
	s := &flipt.Segment{Key: r.Key, Name: r.Name, Description: r.Description, MatchType: r.MatchType}
	m.segments = append(m.segments, s)
	return s, nil
}
func (m *memoryStore) CreateConstraint(_ context.Context, r *flipt.CreateConstraintRequest) (*flipt.Constraint, error) {
	c := &flipt.Constraint{Type: r.Type, Property: r.Property, Operator: r.Operator, Value: r.Value}
	for _, s := range m.segments {
		if s.Key == r.SegmentKey {
			s.Constraints = append(s.Constraints, c)
		}
	}
	return c, nil
}
func (m *memoryStore) CreateRule(_ context.Context, r *flipt.CreateRuleRequest) (*flipt.Rule, error) {
	rule := &flipt.Rule{Id: "rule-id", FlagKey: r.FlagKey, SegmentKey: r.SegmentKey, Rank: r.Rank}
	m.rules = append(m.rules, rule)
	return rule, nil
}
func (m *memoryStore) CreateDistribution(_ context.Context, r *flipt.CreateDistributionRequest) (*flipt.Distribution, error) {
	m.distributions = append(m.distributions, r)
	d := &flipt.Distribution{VariantId: r.VariantId, Rollout: r.Rollout}
	m.rules[len(m.rules)-1].Distributions = append(m.rules[len(m.rules)-1].Distributions, d)
	return d, nil
}

func TestImportExportNativeAttachments(t *testing.T) {
	input := `flags:
- key: feature
  name: Feature
  enabled: true
  variants:
  - key: first
    attachment:
      items:
      - 1
      - false
      - null
      - nested: [text, 2.5]
      7: [true, {deep: null}]
  - key: empty
  rules:
  - segment: users
    rank: 1
    distributions:
    - variant: first
      rollout: 50
segments:
- key: users
  match_type: ANY_MATCH_TYPE
  constraints:
  - type: STRING_COMPARISON_TYPE
    property: country
    operator: eq
    value: US
`
	ctx := context.Background()
	store := new(memoryStore)
	if err := NewImporter(store).Import(ctx, strings.NewReader(input)); err != nil {
		t.Fatal(err)
	}
	if len(store.flags) != 1 || len(store.variants) != 2 || len(store.segments) != 1 || len(store.rules) != 1 || len(store.distributions) != 1 || len(store.segments[0].Constraints) != 1 {
		t.Fatalf("incomplete import: %+v", store)
	}
	if store.variants[1].Attachment != "" {
		t.Fatalf("missing attachment became %q", store.variants[1].Attachment)
	}
	var attachment interface{}
	if err := json.Unmarshal([]byte(store.variants[0].Attachment), &attachment); err != nil {
		t.Fatal(err)
	}
	want := map[string]interface{}{"items": []interface{}{float64(1), false, nil, map[string]interface{}{"nested": []interface{}{"text", 2.5}}}, "7": []interface{}{true, map[string]interface{}{"deep": nil}}}
	if !reflect.DeepEqual(attachment, want) {
		t.Fatalf("attachment = %#v", attachment)
	}
	var out bytes.Buffer
	if err := NewExporter(store).Export(ctx, &out); err != nil {
		t.Fatal(err)
	}
	var doc Document
	if err := yaml.Unmarshal(out.Bytes(), &doc); err != nil {
		t.Fatal(err)
	}
	if _, ok := doc.Flags[0].Variants[0].Attachment.(map[interface{}]interface{}); !ok {
		t.Fatalf("exported attachment is not a YAML map: %s", out.String())
	}
	if doc.Flags[0].Variants[1].Attachment != nil {
		t.Fatalf("empty attachment included: %s", out.String())
	}
	if !strings.Contains(out.String(), "match_type: ANY_MATCH_TYPE") {
		t.Fatalf("segment metadata lost: %s", out.String())
	}
}

func TestImportLegacyJSONAttachment(t *testing.T) {
	store := new(memoryStore)
	if err := NewImporter(store).Import(context.Background(), strings.NewReader("flags:\n- key: f\n  variants:\n  - key: v\n    attachment: '{\"x\":1}'\n")); err != nil {
		t.Fatal(err)
	}
	if store.variants[0].Attachment != `{"x":1}` {
		t.Fatalf("legacy JSON changed: %q", store.variants[0].Attachment)
	}
}

func TestExplicitNullAttachment(t *testing.T) {
	store := new(memoryStore)
	input := "flags:\n- key: f\n  variants:\n  - key: null-value\n    attachment: null\n  - key: absent\n"
	if err := NewImporter(store).Import(context.Background(), strings.NewReader(input)); err != nil {
		t.Fatal(err)
	}
	if store.variants[0].Attachment != "null" || store.variants[1].Attachment != "" {
		t.Fatalf("attachments: %q, %q", store.variants[0].Attachment, store.variants[1].Attachment)
	}
	var out bytes.Buffer
	if err := NewExporter(store).Export(context.Background(), &out); err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out.String(), "attachment: null") || strings.Count(out.String(), "attachment:") != 1 {
		t.Fatalf("null/absent attachments changed: %s", out.String())
	}
}

